import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.DaAAbehN.js";const c=JSON.parse('{"title":"第 14 课：Codex 的\\"技能\\"（Skills）是什么","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-4/lesson-14.md","filePath":"modules/module-4/lesson-14.md"}'),s={name:"modules/module-4/lesson-14.md"};function d(i,t,n,r,h,p){return e(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-14-课-codex-的-技能-skills-是什么" tabindex="-1">第 14 课：Codex 的&quot;技能&quot;（Skills）是什么 <a class="header-anchor" href="#第-14-课-codex-的-技能-skills-是什么" aria-label="Permalink to &quot;第 14 课：Codex 的&quot;技能&quot;（Skills）是什么&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：了解 Codex 内置技能的概念，学会使用技能快速完成复杂任务<br> ⏱️ <strong>预计时长</strong>：20 分钟<br> 🎯 <strong>本节节奏</strong>：讲解 + 实操演示</p></blockquote><hr><h2 id="一、什么是-技能" tabindex="-1">一、什么是&quot;技能&quot;？ <a class="header-anchor" href="#一、什么是-技能" aria-label="Permalink to &quot;一、什么是&quot;技能&quot;？&quot;">​</a></h2><p><strong>技能（Skills）</strong> 是 Codex 内置的预置工作模板。</p><p>你可以把技能想象成 Codex 的&quot;专长领域&quot;——每个技能都是为特定类型的任务预先优化过的。</p><h3 id="类比" tabindex="-1">类比 <a class="header-anchor" href="#类比" aria-label="Permalink to &quot;类比&quot;">​</a></h3><p>如果 Codex 是一个全能助手：</p><ul><li><strong>没有技能</strong> = 你告诉它&quot;帮我做 PPT&quot;，它从零开始猜怎么做</li><li><strong>有技能</strong> = 你告诉它&quot;用 PPT 技能帮我做一份演示文稿&quot;，它直接套用最佳实践</li></ul><hr><h2 id="二、codex-有哪些常用技能" tabindex="-1">二、Codex 有哪些常用技能？ <a class="header-anchor" href="#二、codex-有哪些常用技能" aria-label="Permalink to &quot;二、Codex 有哪些常用技能？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能名称</th><th>用途</th><th>适合人群</th></tr></thead><tbody><tr><td>PPT 生成</td><td>根据主题自动生成演示文稿</td><td>职场人士、学生</td></tr><tr><td>网页开发</td><td>生成 HTML/CSS/JS 网页</td><td>任何想快速建站的人</td></tr><tr><td>数据分析</td><td>读取数据文件并生成分析报告</td><td>分析师、运营</td></tr><tr><td>代码生成</td><td>根据自然语言描述生成代码</td><td>开发者、学习者</td></tr><tr><td>文档整理</td><td>自动整理和格式化文档</td><td>行政、文秘</td></tr><tr><td>图片处理</td><td>调整图片尺寸、格式转换等</td><td>设计师、内容创作者</td></tr></tbody></table><blockquote><p>💡 <strong>提示</strong>：具体可用的技能列表可能随版本更新而变化，请以实际界面为准。</p></blockquote><hr><h2 id="三、实操一-用-ppt-技能生成演示文稿" tabindex="-1">三、实操一：用 PPT 技能生成演示文稿 <a class="header-anchor" href="#三、实操一-用-ppt-技能生成演示文稿" aria-label="Permalink to &quot;三、实操一：用 PPT 技能生成演示文稿&quot;">​</a></h2><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li><p>打开 Codex，找到&quot;技能&quot;或&quot;扩展&quot;面板</p></li><li><p>选择&quot;PPT 生成&quot;技能</p></li><li><p>输入指令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个关于&quot;2026 年 AI 发展趋势&quot;的演示文稿</span></span>
<span class="line"><span>要求：10 页左右，包含封面、目录、主要趋势分析、总结</span></span></code></pre></div></li><li><p>Codex 会：</p><ul><li>联网搜索相关信息</li><li>生成大纲</li><li>创建每一页的内容</li><li>应用合适的模板和配色</li></ul></li><li><p>审查生成的 PPT，根据需要提出修改意见</p></li></ol><hr><h2 id="四、实操二-用网页开发技能做一个小游戏" tabindex="-1">四、实操二：用网页开发技能做一个小游戏 <a class="header-anchor" href="#四、实操二-用网页开发技能做一个小游戏" aria-label="Permalink to &quot;四、实操二：用网页开发技能做一个小游戏&quot;">​</a></h2><h3 id="步骤-1" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>选择&quot;网页开发&quot;技能</li><li>输入指令：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个简单的贪吃蛇游戏网页</span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>- 使用键盘方向键控制蛇的移动</span></span>
<span class="line"><span>- 吃到食物后蛇身变长，分数增加</span></span>
<span class="line"><span>- 碰到边界或自身则游戏结束</span></span>
<span class="line"><span>- 界面简洁美观</span></span></code></pre></div></li><li>Codex 会生成完整的 HTML + CSS + JavaScript 代码</li><li>保存为 <code>snake.html</code>，在浏览器中打开即可游玩</li></ol><hr><h2 id="五、如何自定义技能" tabindex="-1">五、如何自定义技能？ <a class="header-anchor" href="#五、如何自定义技能" aria-label="Permalink to &quot;五、如何自定义技能？&quot;">​</a></h2><p>当你发现某个任务经常要做时，可以让 Codex 帮你创建一个可复用的技能模板。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我每个月都要做一份销售汇总报告，你能帮我创建一个自动化技能吗？</span></span></code></pre></div><p>Codex 可能会：</p><ol><li>分析你过去的报告格式</li><li>创建一个模板文件</li><li>每次只需填入新数据就能自动生成报告</li></ol><hr><h2 id="六、本节实操任务清单" tabindex="-1">六、本节实操任务清单 <a class="header-anchor" href="#六、本节实操任务清单" aria-label="Permalink to &quot;六、本节实操任务清单&quot;">​</a></h2><p>请按顺序完成以下任务：</p><ul><li>[ ] 浏览 Codex 的技能列表，了解可用技能</li><li>[ ] 使用 PPT 技能生成一份简单的演示文稿</li><li>[ ] 使用网页开发技能创建一个简单的小游戏或工具</li><li>[ ] 思考：哪个技能对你的工作最有用？</li></ul><hr><h2 id="七、本节小结" tabindex="-1">七、本节小结 <a class="header-anchor" href="#七、本节小结" aria-label="Permalink to &quot;七、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>技能是什么</td><td>预置的工作模板，让 Codex 更高效地完成特定任务</td></tr><tr><td>常用技能</td><td>PPT 生成、网页开发、数据分析、代码生成等</td></tr><tr><td>使用方法</td><td>在技能面板选择 → 输入指令 → 审查结果</td></tr><tr><td>自定义技能</td><td>可以将常用流程固化为可复用模板</td></tr></tbody></table><hr><h2 id="八、下一步" tabindex="-1">八、下一步 <a class="header-anchor" href="#八、下一步" aria-label="Permalink to &quot;八、下一步&quot;">​</a></h2><p><a href="./../module-5/project-1.html">→ 进入模块五：项目实战</a></p>`,38)])])}const b=a(s,[["render",d]]);export{c as __pageData,b as default};
